    wire [23:0] p = a_i ^ b_i;
    wire [23:0] g = a_i & b_i;

    // Block-level (3-bit blocks) generate/propagate, 8 blocks
    wire [7:0] G0, P0;

    genvar j;
    generate
        for (j = 0; j < 8; j = j + 1) begin : blockGP
            wire g0 = g[3*j+0];
            wire g1 = g[3*j+1];
            wire g2 = g[3*j+2];
            wire p0 = p[3*j+0];
            wire p1 = p[3*j+1];
            wire p2 = p[3*j+2];

            assign G0[j] = g2 | (p2 & g1) | (p2 & p1 & g0);
            assign P0[j] = p0 & p1 & p2;
        end
    endgenerate

    // Kogge-Stone prefix tree over 8 blocks (strides 1,2,4)
    wire [7:0] G1, P1, G2, P2, G3;

    generate
        for (j = 0; j < 8; j = j + 1) begin : lvl1
            if (j >= 1) begin
                assign G1[j] = G0[j] | (P0[j] & G0[j-1]);
                assign P1[j] = P0[j] & P0[j-1];
            end else begin
                assign G1[j] = G0[j];
                assign P1[j] = P0[j];
            end
        end
    endgenerate

    generate
        for (j = 0; j < 8; j = j + 1) begin : lvl2
            if (j >= 2) begin
                assign G2[j] = G1[j] | (P1[j] & G1[j-2]);
                assign P2[j] = P1[j] & P1[j-2];
            end else begin
                assign G2[j] = G1[j];
                assign P2[j] = P1[j];
            end
        end
    endgenerate

    generate
        for (j = 0; j < 8; j = j + 1) begin : lvl3
            if (j >= 4) begin
                assign G3[j] = G2[j] | (P2[j] & G2[j-4]);
            end else begin
                assign G3[j] = G2[j];
            end
        end
    endgenerate

    // Block carry-ins
    wire [7:0] cin;
    assign cin[0] = 1'b0;
    generate
        for (j = 1; j < 8; j = j + 1) begin : cingen
            assign cin[j] = G3[j-1];
        end
    endgenerate

