    wire [23:0] sum;
    generate
        for (j = 0; j < 8; j = j + 1) begin : resolve
            wire g0 = g[3*j+0];
            wire g1 = g[3*j+1];
            wire p0 = p[3*j+0];
            wire p1 = p[3*j+1];
            wire p2 = p[3*j+2];

            wire c0 = cin[j];
            wire c1 = g0 | (p0 & c0);
