            assign sum[3*j+1] = p1 ^ c1;
            assign sum[3*j+2] = p2 ^ c2;
        end
    endgenerate

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 24'd0;
        end else begin
            valid_o <= valid_i;
            if (valid_i)
