module addpipe24 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [23:0] a_i,
    input  wire [23:0] b_i,
    output reg          valid_o,
    output reg  [23:0] y_o
);

    wire [23:0] p = a_i ^ b_i;
    wire [23:0] g = a_i & b_i;

    wire [23:0] sum;
    wire [5:0]  cin_block;
    wire [5:0]  cout_block;
    wire [5:0]  Pblk;

    assign cin_block[0] = 1'b0;

    genvar k;
    generate
        for (k = 0; k < 6; k = k + 1) begin : blk
            wire c0 = cin_block[k];
            wire c1 = g[4*k+0] | (p[4*k+0] & c0);
            wire c2 = g[4*k+1] | (p[4*k+1] & c1);
            wire c3 = g[4*k+2] | (p[4*k+2] & c2);
            wire c4 = g[4*k+3] | (p[4*k+3] & c3);

            assign Pblk[k]       = p[4*k+0] & p[4*k+1] & p[4*k+2] & p[4*k+3];
            assign cout_block[k] = Pblk[k] ? c0 : c4;

            assign sum[4*k+0] = p[4*k+0] ^ c0;
            assign sum[4*k+1] = p[4*k+1] ^ c1;
            assign sum[4*k+2] = p[4*k+2] ^ c2;
            assign sum[4*k+3] = p[4*k+3] ^ c3;
        end
    endgenerate

    generate
        for (k = 1; k < 6; k = k + 1) begin : chain
            assign cin_block[k] = cout_block[k-1];
        end
    endgenerate

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 24'd0;
        end else begin
            valid_o <= valid_i;
            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe24 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [23:0] a_i,
    input  wire [23:0] b_i,
    output reg          valid_o,
    output reg  [23:0] y_o
);

    wire [23:0] p = a_i ^ b_i;
    wire [23:0] g = a_i & b_i;

    // 8 blocks of 3 bits: block-level generate/propagate
    wire [7:0] G, P;

    genvar j;
    generate
        for (j = 0; j < 8; j = j + 1) begin : blk
            wire g0 = g[3*j+0];
            wire g1 = g[3*j+1];
            wire g2 = g[3*j+2];
            wire p0 = p[3*j+0];
            wire p1 = p[3*j+1];
            wire p2 = p[3*j+2];

            assign G[j] = g2 | (p2 & g1) | (p2 & p1 & g0);
            assign P[j] = p0 & p1 & p2;
        end
    endgenerate

    // Flat (non-staged) sum-of-products block carry-ins.
    // Letting the synthesis optimizer (ABC) freely re-balance this
    // expression tree, rather than forcing an explicit multi-level
    // prefix structure, has empirically produced better WNS in prior
    // attempts (cla_block4 flat vs cla_block4_kstree staged).
    wire [7:0] cin;
    assign cin[0] = 1'b0;
    assign cin[1] = G[0];
    assign cin[2] = G[1] | (P[1] & G[0]);
    assign cin[3] = G[2] | (P[2] & G[1]) | (P[2] & P[1] & G[0]);
    assign cin[4] = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) |
                    (P[3] & P[2] & P[1] & G[0]);
    assign cin[5] = G[4] | (P[4] & G[3]) | (P[4] & P[3] & G[2]) |
                    (P[4] & P[3] & P[2] & G[1]) |
                    (P[4] & P[3] & P[2] & P[1] & G[0]);
    assign cin[6] = G[5] | (P[5] & G[4]) | (P[5] & P[4] & G[3]) |
                    (P[5] & P[4] & P[3] & G[2]) |
                    (P[5] & P[4] & P[3] & P[2] & G[1]) |
                    (P[5] & P[4] & P[3] & P[2] & P[1] & G[0]);
    assign cin[7] = G[6] | (P[6] & G[5]) | (P[6] & P[5] & G[4]) |
                    (P[6] & P[5] & P[4] & G[3]) |
                    (P[6] & P[5] & P[4] & P[3] & G[2]) |
                    (P[6] & P[5] & P[4] & P[3] & P[2] & G[1]) |
                    (P[6] & P[5] & P[4] & P[3] & P[2] & P[1] & G[0]);

    // Intra-block (3-bit) carry resolve + sum
    wire [23:0] sum;
    generate
        for (j = 0; j < 8; j = j + 1) begin : resolve
            wire g0 = g[3*j+0];
            wire g1 = g[3*j+1];
            wire p0 = p[3*j+0];
            wire p1 = p[3*j+1];
            wire p2 = p[3*j+2];

            wire c0 = cin[j];
            wire c1 = g0 | (p0 & c0);
            wire c2 = g1 | (p1 & g0) | (p1 & p0 & c0);

            assign sum[3*j+0] = p0 ^ c0;
            assign sum[3*j+1] = p1 ^ c1;
            assign sum[3*j+2] = p2 ^ c2;
        end
    endgenerate

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 24'd0;
        end else begin
            valid_o <= valid_i;
            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe24 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [23:0] a_i,
    input  wire [23:0] b_i,
    output reg          valid_o,
    output reg  [23:0] y_o
);

    // Bit-level generate/propagate
    wire [23:0] p0 = a_i ^ b_i;
    wire [23:0] g0 = a_i & b_i;

    // Vectorized Kogge-Stone prefix stages using shift+mask instead of
    // per-bit generate assigns, to let the synthesizer treat each stage
    // as a single word-level shift/AND/OR op and share logic more freely.

    localparam [23:0] MASK1  = 24'h000001;
    localparam [23:0] MASK2  = 24'h000003;
    localparam [23:0] MASK4  = 24'h00000F;
    localparam [23:0] MASK8  = 24'h0000FF;

    wire [23:0] g1, p1;
    assign g1 = g0 | (p0 & (g0 << 1));
    assign p1 = (p0 & (p0 << 1)) | (p0 & MASK1);

    wire [23:0] g2, p2;
    assign g2 = g1 | (p1 & (g1 << 2));
    assign p2 = (p1 & (p1 << 2)) | (p1 & MASK2);

    wire [23:0] g3, p3;
    assign g3 = g2 | (p2 & (g2 << 4));
    assign p3 = (p2 & (p2 << 4)) | (p2 & MASK4);

    wire [23:0] g4, p4;
    assign g4 = g3 | (p3 & (g3 << 8));
    assign p4 = (p3 & (p3 << 8)) | (p3 & MASK8);

    wire [23:0] g5;
    assign g5 = g4 | (p4 & (g4 << 16));
    // p5 not needed: this is the final prefix stage.

    // carry-in to bit i (i>=1) = cumulative generate through bit i-1;
    // carry-in to bit 0 = 0. Expressed as a single left shift.
    wire [23:0] c = {g5[22:0], 1'b0};

    wire [23:0] sum = p0 ^ c;

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 24'd0;
        end else begin
            valid_o <= valid_i;
            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe24 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [23:0] a_i,
    input  wire [23:0] b_i,
    output reg          valid_o,
    output reg  [23:0] y_o
);

    wire [23:0] p = a_i ^ b_i;
    wire [23:0] g = a_i & b_i;

    wire [23:0] c;
    assign c[0] = 1'b0;

    genvar i, k;
    generate
        for (i = 1; i < 24; i = i + 1) begin : cbit
            wire [i-1:0] terms;
            for (k = 0; k < i; k = k + 1) begin : kterm
                if (k == i-1) begin
                    assign terms[k] = g[k];
                end else begin
                    // g[k] AND (AND of p[m] for m = k+1 .. i-1)
                    assign terms[k] = g[k] & (&p[i-1:k+1]);
                end
            end
            assign c[i] = |terms;
        end
    endgenerate

    wire [23:0] sum;
    assign sum[0] = p[0];
    generate
        for (i = 1; i < 24; i = i + 1) begin : sumbit
            assign sum[i] = p[i] ^ c[i];
        end
    endgenerate

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 24'd0;
        end else begin
            valid_o <= valid_i;
            if (valid_i)
                y_o <= sum;
        end
    end

endmodule
